import assert from'node:assert/strict';import{mkdir,writeFile}from'node:fs/promises';const{chromium}=await import(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const out='docs/qa/layout-audit-2026-11-16/round3';await mkdir(out,{recursive:true});const b=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--mute-audio']});const results=[];
try{const p=await b.newPage({viewport:{width:1100,height:1400},isMobile:true,hasTouch:true});for(const layout of['original','balanced','oval','classic'])for(const[width,height]of[[320,400],[375,500],[440,782]])for(const scale of[90,95,100,105,110]){
 await p.goto('http://127.0.0.1:4179/tests/fixtures/layout-audit.html?'+new URLSearchParams({layout,width,height,scale,scene:'acting-other',long:1}),{waitUntil:'domcontentloaded'});await p.locator('#audit-stage[data-ready=true]').waitFor();
 const metrics=await p.locator('#audit-stage').evaluate(root=>{const r=e=>{const b=e.getBoundingClientRect();return{x:b.x,y:b.y,w:b.width,h:b.height};};return{names:[...root.querySelectorAll('.mx-seat:not(.mx-seat-mine)')].filter(e=>e.querySelector('.mx-player-name')?.checkVisibility()).map(e=>({name:r(e.querySelector('.mx-player-name')),avatar:r(e.querySelector('.mx-avatar-fallback')),bubble:e.querySelector('.mx-player-action')?.checkVisibility()?r(e.querySelector('.mx-player-action')):null})),cards:[...root.querySelectorAll('.mx-board:not([hidden]) .mx-public-slot')].map(r)};});
 if(layout!=='original')for(const n of metrics.names){assert.ok(n.name.y+n.name.h<n.avatar.y,`${layout} ${width} ${scale}: nickname touches avatar`);if(n.bubble)assert.ok(n.name.y+n.name.h<n.bubble.y,`${layout} ${width} ${scale}: nickname touches bubble`);}
 for(let i=1;i<metrics.cards.length;i++){const gap=metrics.cards[i].x-metrics.cards[i-1].x-metrics.cards[i-1].w;assert.ok(layout==='original'?gap>1:Math.abs(gap)<.3,`${layout}: wrong card gap ${gap}`);}
 const id=`${layout}-${width}-${scale}`;if(scale===100||scale===110)await p.locator('#audit-stage').screenshot({path:`${out}/${id}.png`});results.push({id,layout,width,height,scale,pass:true,metrics});
}console.log(results.length+' layout distinction checks passed');}finally{await b.close();await writeFile(out+'/results.json',JSON.stringify(results,null,2));}
